// — runs against the remaining budget. PostCommit handles sessions with pending
// files; doctor retries no-file ENDED sessions. Agents whose session-end hook
// has a normal timeout should not implement this.
type SessionEndBudgeter interface {
	Agent

	// SessionEndBudget returns the wall-clock budget for the whole session-end
	// hook invocation, measured from process start. A non-positive value means
	// no budget applies.
	SessionEndBudget() time.Duration
}

// TurnEndBudgeter is implemented by agents whose host bounds the hook that ends
// a turn. Entire bounds the network-bound part of turn-end checkpoint
// finalization by it, so a slow remote makes Entire give up on the remaining
// checkpoints instead of the host killing the hook before the session state is
// saved. Agents that do not implement it get a conservative default.
type TurnEndBudgeter interface {
	Agent

	// TurnEndBudget returns how long the turn-end hook may run, measured from
	// process start, leaving headroom for the work after finalization. Derive
	// it from the hook timeout with TurnEndBudgetWithin. Zero means no time to
	// finalize, so Entire skips it; unlike SessionEndBudget, it never means
	// unbounded.
	TurnEndBudget() time.Duration
}

// TurnEndBudgetWithin returns the turn-end budget for a host hook timeout. It
// keeps a fifth of the timeout, between 2s and 10s, for what the hook does
// after finalization (saving session state) and for the shell wrapper and
// binary load that run before Entire's clock starts.
func TurnEndBudgetWithin(hookTimeout time.Duration) time.Duration {
	headroom := min(max(hookTimeout/5, 2*time.Second), 10*time.Second)
	return max(hookTimeout-headroom, 0)
}

// RestoredSessionPathResolver is implemented by agents that need a
// transcript-specific path when Entire reconstructs a session from checkpoint
// metadata. This is used for restored sessions only; live sessions still use
// the agent's native hook/session references.
type RestoredSessionPathResolver interface {
	Agent

	// ResolveRestoredSessionFile returns where Entire should write a restored
	// transcript so the agent can discover it later.
//   - SessionFileCandidatesProvider
//   - SidecarImageProvider
//   - SkillDiscoverer
//   - SkillEventExtractor
//   - StaleHookReporter
//   - SubagentSessionResolver
//   - TaskTranscriptMatcher
//   - ToolInvocationScanner
//   - TranscriptFetcher
//   - TranscriptSanitizer
//   - TurnEndBudgeter
//
// Their As* helpers resolve through builtinCapability, or through
// nonDeclarerCapability for the entries marked as refusing CapabilityDeclarer
// agents. Callers reach every capability through its As* helper, never by
// type-asserting an agent directly.
type DeclaredCaps struct {
	Hooks                  bool `json:"hooks"`
	TranscriptAnalyzer     bool `json:"transcript_analyzer"`
	TranscriptPreparer     bool `json:"transcript_preparer"`
	TokenCalculator        bool `json:"token_calculator"`
	return builtinCapability[SkillEventExtractor](ag)
}

// AsToolInvocationScanner returns the agent as ToolInvocationScanner if it
// implements the interface. Built-in only: reading tool calls out of a
// transcript needs knowledge of that transcript's shape, which an external
// agent's parse-hook does not convey.
func AsToolInvocationScanner(ag Agent) (ToolInvocationScanner, bool) {
	return builtinCapability[ToolInvocationScanner](ag)
}

// AsSessionEndBudgeter returns the agent as SessionEndBudgeter if it implements
// the interface. Built-in only because no external agent needs it yet — not
// because external agents could enforce a budget themselves: a plugin supplies
// only parse-hook, while the work being bounded (endSessionNow, the condense)
// runs in the entire process. Widen DeclaredCaps with a session_end_budget
// field when an external agent has a host that clamps its session-end hook.
func AsSessionEndBudgeter(ag Agent) (SessionEndBudgeter, bool) {
	return builtinCapability[SessionEndBudgeter](ag)
}

// AsTurnEndBudgeter returns the agent as TurnEndBudgeter if it implements the
// interface. Built-in only: the bounded work runs in the entire process, and the
// external-agent protocol carries no host hook timeout to derive a budget from.
func AsTurnEndBudgeter(ag Agent) (TurnEndBudgeter, bool) {
	return builtinCapability[TurnEndBudgeter](ag)
